=== FILE: deep_counter_props.sv ===
// Formal wrapper and interface properties for deep_counter.
// Properties follow interface_spec.md section 3 (req tags noted per assertion).
// Written in the immediate-assertion subset read by the open Yosys front end.
module deep_counter_formal #(
    parameter integer LIMIT = 99
) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire clr
);
    wire [6:0] count;
    wire       carry;

    deep_counter #(.LIMIT(LIMIT)) dut (
        .clk  (clk),
        .rst_n(rst_n),
        .en   (en),
        .clr  (clr),
        .count(count),
        .carry(carry)
    );

    // First-cycle guard for $past.
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    // Environment: the specification describes behaviour after reset, so the
    // first clock edge is a reset edge. No other input is constrained.
    always @(*)
        if (!f_past_valid)
            assume(!rst_n);

    // [req:DC-CARRY] carry is high exactly when en, !clr and count == LIMIT,
    // combinationally.
    always @(*)
        assert(carry == (en && !clr && (count == LIMIT)));

    always @(posedge clk) begin
        // [req:DC-RANGE] count never above LIMIT (also the induction invariant).
        if (f_past_valid)
            assert(count <= LIMIT);

        // [req:DC-RESET] reset low at an edge clears count.
        if (f_past_valid && !$past(rst_n))
            assert(count == 7'd0);

        // [req:DC-CLEAR] clear clears count whatever en is.
        if (f_past_valid && $past(rst_n) && $past(clr))
            assert(count == 7'd0);

        // [req:DC-COUNT] enabled count below LIMIT steps up by one.
        if (f_past_valid && $past(rst_n) && !$past(clr) && $past(en)
                && ($past(count) < LIMIT))
            assert(count == $past(count) + 7'd1);

        // [req:DC-COUNT] enabled count at LIMIT wraps to 0.
        if (f_past_valid && $past(rst_n) && !$past(clr) && $past(en)
                && ($past(count) == LIMIT))
            assert(count == 7'd0);

        // [req:DC-HOLD] no clear, no enable: count does not change.
        if (f_past_valid && $past(rst_n) && !$past(clr) && !$past(en))
            assert(count == $past(count));
    end

    // Non-vacuity covers for the scenarios the proof must still allow.
    always @(posedge clk) begin
        // Counter reaches its last value (about 100 enabled cycles after reset).
        cover(f_past_valid && (count == LIMIT));
        // Carry out is driven.
        cover(f_past_valid && carry);
        // The wrap from LIMIT to 0 happens.
        cover(f_past_valid && $past(rst_n) && $past(carry) && (count == 7'd0));
        // The top bit of count is exercised.
        cover(f_past_valid && count[6]);
        // A clear during a count, with en also high.
        cover(f_past_valid && $past(rst_n) && $past(clr) && $past(en)
              && ($past(count) != 7'd0));
        // A hold at a non-zero value.
        cover(f_past_valid && $past(rst_n) && !$past(clr) && !$past(en)
              && ($past(count) != 7'd0));
    end
endmodule
